using UnityEngine;
using UnityEngine.UI;

// Small original UI glyphs share one pixel grid and palette.
[RequireComponent(typeof(CanvasRenderer))]
public class PixelIcon : MaskableGraphic
{
    public enum Kind { Star, Book, Document, Terminal, Play, Eraser, Bulb, Python, Cloud, Blocks }
    public Kind kind;
    static readonly Color Ink=new Color32(28,39,91,255), Gold=new Color32(255,211,102,255), Light=new Color32(255,246,202,255), Shade=new Color32(215,146,68,255), Purple=new Color32(166,151,222,255), Blue=new Color32(80,139,206,255);
    protected override void OnPopulateMesh(VertexHelper vh)
    {
        vh.Clear();
        string[] rows;
        switch(kind)
        {
            case Kind.Star: rows=new[]{".......11.......","......1221......","......1231......",".....122231.....",".11111222311111.","1222222222222231",".12222222222231.","..122122221231..","...1222222231...","...1222222231...","..122222222231..","..122231122231..","..12311..11231..","..111......111.."};break;
            case Kind.Book: rows=new[]{"................",".111111..111111.","1444444114444441","1444444114444441","1441444114414441","1444144114144441","1444444114444441","1441444114414441","1444444114444441","1444444114444441","1444444114444441",".11111111111111.","..555551155555..","...1111111111..."};break;
            case Kind.Document: rows=new[]{"...1111111111...","..144444444441..","..145544444441..","..145544444441..","..144444444441..","..141111111441..","..144444444441..","..141111111441..","..144444444441..","..141111111441..","..144444444441..","..141111144441..","..144444444441..","...1111111111..."};break;
            case Kind.Terminal: rows=new[]{".11111111111111.","1111111111111111","1144111111111111","1114411111111111","1111441111111111","1111144111111111","1111441111111111","1114411111111111","1144111444444111","1111111111111111","1111111111111111",".11111111111111."};break;
            case Kind.Play: rows=new[]{"..11............","..1111..........","..111111........","..11111111......","..1111111111....","..111111111111..","..1111111111....","..11111111......","..111111........","..1111..........","..11............"};break;
            case Kind.Eraser: rows=new[]{"................",".........11.....","........1551....",".......155551...","......15555551..",".....1555555551.","....1455555551..","...1444555551...","..1444445551....",".1444444451.....","..14444441......","...144441.......","....1111111111.."};break;
            case Kind.Bulb: rows=new[]{".....111111.....","...1122222211...","..122444422221..","..124422222221..","..124222222221..","..122222222221..","...1222222221...","....12222221....",".....122221.....",".....111111.....",".....155551.....",".....111111.....","......1551......",".......11......."};break;
            case Kind.Python: rows=new[]{"....66666666....","...6664666666...","...6666666666...",".......666666...","..6666666666622.",".666666666666222","6666666666662222","6666622222222222","6666222222222222",".66622222222222.","..662222222222..","...222222.......","...2222222222...","...2222224222...","....22222222...."};break;
            case Kind.Cloud: rows=new[]{".....4444...............","...44444444.............","..4444444444....444......",".444444444444..44444.....","4444444444444444444444...","44444555555544444444444..","445555555555555555555555","555555555555555555555555"};break;
            default: rows=new[]{".....111111.....",".....133331.....",".....134431.....",".....131131.....",".....134431.....",".....133331.....",".11111111111111.",".16666611222221.",".16446611244221.",".16644611242221.",".16446611244221.",".16666611222221.",".11111111111111."};break;
        }
        int columns=0;foreach(var row in rows)columns=Mathf.Max(columns,row.Length);
        var r=rectTransform.rect;float cell=Mathf.Min(r.width/columns,r.height/rows.Length);
        float left=r.center.x-columns*.5f*cell,top=r.center.y+rows.Length*cell/2;
        for(int y=0;y<rows.Length;y++)for(int x=0;x<rows[y].Length;x++)
        {
            char p=rows[y][x];if(p=='.')continue;
            Color c=p=='1'?Ink:p=='2'?Gold:p=='3'?Shade:p=='4'?Light:p=='5'?Purple:Blue;
            if(kind==Kind.Cloud)c=p=='4'?new Color32(195,210,245,255):new Color32(166,184,228,255);
            c*=color;int n=vh.currentVertCount;float a=left+x*cell,b=top-y*cell;
            vh.AddVert(new Vector3(a,b-cell),c,Vector2.zero);vh.AddVert(new Vector3(a,b),c,Vector2.zero);
            vh.AddVert(new Vector3(a+cell,b),c,Vector2.zero);vh.AddVert(new Vector3(a+cell,b-cell),c,Vector2.zero);
            vh.AddTriangle(n,n+1,n+2);vh.AddTriangle(n,n+2,n+3);
        }
    }
}
